"use strict";

$(document).ready(function() {
    // File Upload
    $(".file-upload").on("change", function() {
        var fileInput = this;
        if (fileInput.files && fileInput.files[0]) {
            var reader = new FileReader();
            reader.onload = function(e) {
                $(".upload-pic").attr("src", e.target.result);
            };
            reader.readAsDataURL(fileInput.files[0]);
        }
    });

    $(".upload-button").on("click", function() {
        $(".file-upload").click();
    });

    // Datepicker
    var dateOfBirthInput = document.getElementById("dateofBirth");
    if (dateOfBirthInput) {
        new Datepicker(dateOfBirthInput, {
            clearBtn: true,
            allowOneSidedRange: true
        });
    }

    // SweetAlert for Delete Account
    $('[data-action-target="#acSecctingsActionMessage"]').on("click", function(e) {
        e.preventDefault();
        const swalWithCustomButtons = Swal.mixin({
            customClass: {
                confirmButton: "btn btn-success m-1",
                cancelButton: "btn btn-danger m-1"
            },
            buttonsStyling: false
        });
        swalWithCustomButtons.fire({
            title: "Delete Account",
            text: "You want to delete this account!!!",
            icon: "warning",
            showCancelButton: true,
            confirmButtonText: "Yes, Delete it!",
            cancelButtonText: "No, cancel!",
            reverseButtons: true
        }).then(result => {
            if (result.value) {
                swalWithCustomButtons.fire("Deleted!", "Account Deleted Successfully.", "success");
            } else if (result.dismiss === Swal.DismissReason.cancel) {
                swalWithCustomButtons.fire("Cancelled", "Your account is safe :)", "error");
            }
        });
    });

    var bgClasses = ['bg-primary', 'bg-warning', 'bg-success', 'bg-green', 'bg-danger', 'bg-info','bg-cyan','bg-light'
        ,'bg-teal','bg-indigo','bg-blue','bg-muted','bg-red','bg-dark'];

    // Pilih semua option di dalam select yang memiliki attribute 'data-language'
    $('#selectLanguages option').each(function() {
        // Pilih kelas background acak dari array
        var randomClass = bgClasses[Math.floor(Math.random() * bgClasses.length)];
        // Set nilai 'data-language' menjadi kelas background acak
        $(this).attr('data-language', randomClass);
    });
});
